import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		Scanner  ch = new Scanner(System.in);
		int t = ch.nextInt();
		while(t-->0){
		    int n = ch.nextInt();
		    int m = 3*n;
		    long [] a = new long[m];
		    for(int i =0;i<m;i++){
		        a[i]= ch.nextLong();
		    }
		    Arrays.sort(a);
		    
		    for(int i =0;i<m/2;i++){
		        long temp = a[i];
		        a[i] = a[m-1-i];
		        a[m-1-i]= temp;
		    }
		    long pre[] = new long[m+1];
		    for(int i =0;i<m;i++){
		        pre[i+1] = pre[i]+a[i];
		    }
		    long ans =0;
		    for( int A = 0; A<=n;A++){
		        int lo = 0;
		        int hi = n-A;
		        while(lo<hi){
		            int B = (lo+hi +1)/2;
		            int r = A+2 *(B-1);
		            int s = 2*A+(B-1);
		            long chan = a[r]+a[r+1]-3 * a[m-s-1];
		            if(chan>=0) lo =B;
		            else hi = B-1;
		        }
		        int B = lo;
		        long val = 2* pre[A]+pre[A+2*B]+3*pre[m-(2*A+B)];
		        ans = Math.max(ans,val);
		        
		        
		        
		        
		        
		        
		        
		        
		        
		        
		        
		    }
		    System.out.println(ans);
		}

	}
}
